def crear_cuenta_y_configuracion(apps, schema_editor):
    """Subcuenta 601.05.05 (no deducible) y la operación COMISIONES_VENTA. Aditiva: get_or_create,
    no toca nada existente. No se usa 601.05.03 porque ahí cae la pauta de Meta (Issue #505)."""
    CuentaContable = apps.get_model('contabilidad', 'CuentaContable')
    ConfiguracionContable = apps.get_model('contabilidad', 'ConfiguracionContable')
    cuenta = CuentaContable.objects.filter(codigo_sat='601.05.05').first()
    if cuenta is None:
        padre = CuentaContable.objects.filter(codigo_sat='601.05').first()
        if padre is None:
            print("Cuenta padre 601.05 no encontrada: no se creó 601.05.05 ni se configuró COMISIONES_VENTA")
            return
        cuenta = CuentaContable.objects.create(
            codigo_sat='601.05.05', nombre='No deducibles - Comisiones y pagos a ventas', tipo='GASTO',
            naturaleza='D', nivel=padre.nivel + 1, padre=padre, permite_movimientos=True)
    ConfiguracionContable.objects.get_or_create(
        operacion='COMISIONES_VENTA',
        defaults={'cuenta': cuenta, 'descripcion': 'Comisiones y pagos al personal de ventas (Issue #505)',
                  'activa': True})


